#![allow(unused_imports)]
use vstd::prelude::*;

// solve(s) returns "Bad" exactly when there is at least one adjacent-equal
// pair in s, and "Good" otherwise.

#[requires(true)]
#[ensures(
    // If there exists an index i with s[i] == s[i+1], then we must return ['B','a','d'].
    (exists |i: usize| i + 1 < s.len() && s[i] == s[i+1])
        ==> result == vec!['B','a','d']
)]
#[ensures(
    // If no such adjacent-equal pair exists, then we must return ['G','o','o','d'].
    (!(exists |i: usize| i + 1 < s.len() && s[i] == s[i+1]))
        ==> result == vec!['G','o','o','d']
)]
fn solve(s: Vec<char>) -> Vec<char> {
    // Check each adjacent pair for equality
    let hard_to_enter = s.windows(2).any(|w| w[0] == w[1]);

    if hard_to_enter {
        vec!['B', 'a', 'd']
    } else {
        vec!['G', 'o', 'o', 'd']
    }
}

fn main() {
    // some quick smoke tests
    assert_eq!(solve(vec!['a','b','c']),     vec!['G','o','o','d']);
    assert_eq!(solve(vec!['a','a','b']),     vec!['B','a','d']);
    assert_eq!(solve(vec!['A','B','C','C']), vec!['B','a','d']);
    assert_eq!(solve(Vec::new()),            vec!['G','o','o','d']);
}